const linkIcon = document.getElementById('link-icon-class');
const imgFile = document.getElementById('img-file-name');
const linkPath = document.getElementById('link-path-part');
const inputNearby = document.getElementById('input-nearby-sibling');
const inputName = document.getElementById('input-by-name');
const imgFig = document.getElementById('img-by-figcaption');

if (!btnTitle || !btnSvg || !btnIcon || !linkIcon || !imgFile || !linkPath || !inputNearby || !inputName || !imgFig) return false;

if (!adapter || !adapter.s || adapter.s.ended) {
  return !btnTitle.hasAttribute('aria-label') && !imgFile.hasAttribute('alt');
}

return btnTitle.getAttribute('aria-label') === 'Account Settings' &&
       btnSvg.getAttribute('aria-label') === 'Close Window' &&
       btnIcon.getAttribute('aria-label') === 'Search' &&
       linkIcon.getAttribute('aria-label') === 'Shopping cart' &&
       imgFile.getAttribute('alt') === 'Download report' &&
       linkPath.getAttribute('aria-label') === 'Customer support' &&
       inputNearby.getAttribute('aria-label') === 'Email Address' &&
       inputName.getAttribute('aria-label') === 'Postal code' &&
       imgFig.getAttribute('alt') === 'Harbor at dawn';

